import {
  MeshStandardNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group
} from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const mainGroup = new Group();

  // 1. CONFIGURATION & PALETTE
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const cInk = new THREE.Color(colors.ink);
  const cPaper = new THREE.Color(colors.paper);
  const cAccent = new THREE.Color(colors.accent);
  const cSurface = new THREE.Color(colors.surface);

  // 2. STAGE BACKDROP (z = -2.5) - Fills the viewport behind the list row
  const bgGeom = new PlaneGeometry(7.5, 6.0);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
    depthWrite: false
  });

  // Vertical gradient from Surface to Ink
  const uvCoords = uv();
  const gradNode = mix(
    vec3(cSurface.r, cSurface.g, cSurface.b),
    vec3(cInk.r, cInk.g, cInk.b),
    smoothstep(0.1, 0.9, uvCoords.y)
  );
  bgMat.colorNode = gradNode;

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  mainGroup.add(bgMesh);

  // Add subtle ambient spotlight locally to make brushed metal pop
  const localSpot = new THREE.SpotLight(colors.paper, 1.2, 8, Math.PI / 4, 0.5, 1);
  localSpot.position.set(2, 3, 4);
  mainGroup.add(localSpot);

  const localRim = new THREE.DirectionalLight(colors.accent, 0.8);
  localRim.position.set(-3, -2, -1);
  mainGroup.add(localRim);

  // 3. THE INTERACTIVE LIST ROW CONTAINER
  const rowGroup = new Group();
  // Lift offset anchor
  const liftAnchor = new Group();
  rowGroup.add(liftAnchor);
  mainGroup.add(rowGroup);

  const rowWidth = 5.2;
  const rowHeight = 0.85;

  // Plane for brushed metal panel
  const rowGeom = new PlaneGeometry(rowWidth, rowHeight);
  const rowMat = new MeshStandardNodeMaterial({
    roughness: 0.52,
    metalness: 0.55,
    color: cSurface
  });

  // Load brushed metal map if available
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(1.5, 0.35);
      rowMat.map = texture;
      rowMat.needsUpdate = true;
    });
  }

  const rowMesh = new Mesh(rowGeom, rowMat);
  liftAnchor.add(rowMesh);

  // 4. ACCENT HIGHLIGHT LINE (Bottom boundary / Divider)
  const lineGeom = new PlaneGeometry(rowWidth, 0.02);
  const lineMat = new MeshStandardNodeMaterial({
    roughness: 0.3,
    metalness: 0.8,
    color: cInk
  });
  const lineMesh = new Mesh(lineGeom, lineMat);
  lineMesh.position.set(0, -rowHeight / 2, 0.01);
  liftAnchor.add(lineMesh);

  // Interactive Accent Border (Left side signal indicator)
  const hoverBorderGeom = new PlaneGeometry(0.04, rowHeight * 0.9);
  const hoverBorderMat = new MeshStandardNodeMaterial({
    color: cAccent,
    emissive: cAccent,
    emissiveIntensity: 0.0
  });
  const hoverBorder = new Mesh(hoverBorderGeom, hoverBorderMat);
  hoverBorder.position.set(-rowWidth / 2 + 0.02, 0, 0.02);
  liftAnchor.add(hoverBorder);

  // 5. TEXT ELEMENT BINDINGS / FALLBACK COPY
  const textGroup = new Group();
  textGroup.position.set(0, 0, 0.03);
  liftAnchor.add(textGroup);

  let numStr = '01';
  let titleStr = 'CHRONO MONOPUSHER';
  let descStr = 'AUTOMATIC / CALIBRE NA-18';
  let valueStr = 'CHF 12,400';

  const boundText = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  if (boundText.length > 0) {
    if (boundText[0]?.text) titleStr = boundText[0].text.toUpperCase();
    if (boundText[1]?.text) descStr = boundText[1].text.toUpperCase();
    if (boundText[2]?.text) valueStr = boundText[2].text.toUpperCase();
  }

  // Row Number
  const numText = ctx.fontAtlas.createText(numStr, {
    fontSize: 0.09,
    color: colors.accent,
    align: 'left'
  });
  numText.position.set(-rowWidth / 2 + 0.18, 0.08, 0);
  textGroup.add(numText);

  // Product Title
  const titleText = ctx.fontAtlas.createText(titleStr, {
    fontSize: 0.18,
    color: colors.paper,
    align: 'left'
  });
  titleText.position.set(-rowWidth / 2 + 0.5, -0.06, 0);
  textGroup.add(titleText);

  // Subtitle / Specifications
  const descText = ctx.fontAtlas.createText(descStr, {
    fontSize: 0.09,
    color: '#8b8d99',
    align: 'left'
  });
  descText.position.set(-rowWidth / 2 + 0.5, 0.12, 0);
  textGroup.add(descText);

  // Right Hand Side Value (Price / Badge)
  const valText = ctx.fontAtlas.createText(valueStr, {
    fontSize: 0.13,
    color: colors.paper,
    align: 'right'
  });
  valText.position.set(rowWidth / 2 - 0.25, 0.0, 0);
  textGroup.add(valText);

  // 6. INTERACTION LOGIC
  const rootTimeline = gsap.timeline({ paused: true });

  // Hover visual system: subtle rise lift, light-up left neon edge, shift divider color
  rootTimeline.to(liftAnchor.position, {
    y: 0.15,
    z: 0.18,
    duration: 0.4,
    ease: 'power3.out'
  });
  rootTimeline.to(hoverBorderMat, {
    emissiveIntensity: 1.8,
    duration: 0.3,
    ease: 'power2.out'
  }, 0);
  rootTimeline.to(lineMat.color, {
    r: cAccent.r,
    g: cAccent.g,
    b: cAccent.b,
    duration: 0.4
  }, 0);

  // Save targets for explicit manipulation on events
  const hitPlaneGeom = new PlaneGeometry(rowWidth, rowHeight);
  const hitPlaneMat = new MeshStandardNodeMaterial({
    visible: false
  });
  const hitMesh = new Mesh(hitPlaneGeom, hitPlaneMat);
  hitMesh.position.set(0, 0, 0.2); // Positioned forward to capture raycasts securely
  rowGroup.add(hitMesh);

  let isHovered = false;

  rowGroup.userData.handlers = {
    pointerover: () => {
      isHovered = true;
      rootTimeline.play();
    },
    pointerout: () => {
      isHovered = false;
      rootTimeline.reverse();
    },
    pointerdown: () => {
      gsap.to(liftAnchor.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.1,
        ease: 'power2.out'
      });
    },
    pointerup: () => {
      gsap.to(liftAnchor.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.3,
        ease: 'back.out(1.7)'
      });
      ctx.emit('hub-collection.select', {
        id: config.id ?? 'row-item',
        title: titleStr
      });
    }
  };

  // 7. CLEANUP
  rowGroup.userData.cleanup = () => {
    rootTimeline.kill();
    bgGeom.dispose();
    bgMat.dispose();
    rowGeom.dispose();
    rowMat.dispose();
    lineGeom.dispose();
    lineMat.dispose();
    hoverBorderGeom.dispose();
    hoverBorderMat.dispose();
    hitPlaneGeom.dispose();
    hitPlaneMat.dispose();
  };

  return mainGroup;
}
